<script setup lang="ts">import{onMounted,ref}from'vue';import{request}from'../../api/client';const orders=ref<any[]>([]);onMounted(async()=>{try{orders.value=(await request('/api/v1/payments/orders?user_id=1&page=1&page_size=50')).items||[]}catch{orders.value=[]}})</script>
<template><section><div class="page-title"><p class="eyebrow">ORDERS</p><h1>My Orders</h1><p>支付订单与权益状态。</p></div><el-card><el-table :data="orders"><el-table-column prop="order_id" label="订单ID"/><el-table-column prop="order_no" label="订单号"/><el-table-column prop="provider" label="渠道"/><el-table-column prop="amount" label="金额"/><el-table-column prop="currency" label="币种"/><el-table-column prop="status" label="状态"/><el-table-column label="操作"><template #default="{row}"><el-button link type="primary" @click="$router.push('/orders/'+row.order_id)">详情</el-button></template></el-table-column></el-table><el-empty v-if="!orders.length" description="暂无订单"/></el-card></section></template>